33	export function formatGridRating(value: unknown): string | undefined {
34	    if (typeof value === 'number' && Number.isFinite(value)) {
35	        return value.toFixed(1);
36	    }
37	
38	    if (typeof value !== 'string') {
39	        return undefined;
40	    }
41	
42	    const trimmed = value.trim();
43	    if (!trimmed) {
44	        return undefined;
45	    }
46	
47	    const numericRating = Number.parseFloat(trimmed);
48	    return Number.isFinite(numericRating) ? numericRating.toFixed(1) : trimmed;
49	}
50	
51	export function resolveGridRating(
52	    item: Pick<GridListItem, 'rating' | 'rating_imdb'>
53	): string | undefined {
54	    return formatGridRating(item.rating_imdb) ?? formatGridRating(item.rating);
55	}
