1	import { NgComponentOutlet } from '@angular/common';
2	import {
3	    ChangeDetectionStrategy,
4	    Component,
5	    computed,
6	    DestroyRef,
7	    ElementRef,
8	    inject,
9	    OnInit,
10	} from '@angular/core';
11	import { takeUntilDestroyed, toSignal } from '@angular/core/rxjs-interop';
12	import { map } from 'rxjs/operators';
13	import { MatIconButton } from '@angular/material/button';
14	import { MatIcon } from '@angular/material/icon';
15	import { MatMenuModule } from '@angular/material/menu';
16	import { MatPaginatorModule, PageEvent } from '@angular/material/paginator';
17	import { MatTooltip } from '@angular/material/tooltip';
18	import { ActivatedRoute, Router } from '@angular/router';
19	import { TranslatePipe, TranslateService } from '@ngx-translate/core';
20	import {
21	    GridListComponent,
22	    PlaylistErrorViewComponent,
23	} from '@iptvnator/portal/shared/ui';
24	import {
25	    clearNavigationStateKeys,
26	    getOpenStalkerItemState,
27	    PortalCatalogFacade,
28	    OPEN_STALKER_ITEM_STATE_KEY,
29	    PORTAL_CATALOG_DETAIL_COMPONENT,
30	    PORTAL_CATALOG_FACADE,
31	    PortalCatalogSortMode,
32	} from '@iptvnator/portal/shared/util';
33	
34	interface CategoryContentItem {
35	    id?: number | string;
36	    is_series?: number | string | boolean;
37	    xtream_id?: number | string;
38	    series_id?: number | string;
39	    stream_id?: number | string;
40	    category_id?: number | string;
41	    [key: string]: unknown;
42	}
43	
44	@Component({
45	    selector: 'app-category-content-view',
46	    templateUrl: './category-content-view.component.html',
47	    styleUrls: ['./category-content-view.component.scss'],
48	    changeDetection: ChangeDetectionStrategy.OnPush,
49	    imports: [
50	        GridListComponent,
51	        MatIcon,
52	        MatIconButton,
53	        MatMenuModule,
54	        MatPaginatorModule,
55	        MatTooltip,
56	        NgComponentOutlet,
57	        PlaylistErrorViewComponent,
58	        TranslatePipe,
59	    ],
60	})
61	export class CategoryContentViewComponent implements OnInit {
62	    private readonly activatedRoute = inject(ActivatedRoute);
63	    private readonly destroyRef = inject(DestroyRef);
64	    private readonly hostElement = inject(ElementRef<HTMLElement>);
65	    private readonly router = inject(Router);
66	    private readonly translate = inject(TranslateService);
67	    private readonly catalog = inject(
68	        PORTAL_CATALOG_FACADE
69	    ) as PortalCatalogFacade<
70	        CategoryContentItem,
71	        CategoryContentItem,
72	        CategoryContentItem
73	    >;
74	
75	    readonly detailComponent = inject(PORTAL_CATALOG_DETAIL_COMPONENT);
76	    readonly contentType = this.catalog.contentType;
77	    readonly limit = this.catalog.limit;
78	    readonly pageIndex = this.catalog.pageIndex;
79	    readonly pageSizeOptions = Array.from(this.catalog.pageSizeOptions);
80	    readonly selectedCategory = this.catalog.selectedCategory;
81	    readonly paginatedContent = this.catalog.paginatedContent;
82	    readonly selectedCategoryTitle = this.catalog.selectedCategoryTitle;
83	    readonly categoryItemCount = this.catalog.categoryItemCount;
84	    readonly selectedItem = this.catalog.selectedItem;
85	    readonly totalPages = this.catalog.totalPages;
86	    readonly contentSortMode = this.catalog.contentSortMode;
87	    readonly isPaginatedContentLoading = this.catalog.isPaginatedContentLoading;
88	    readonly isXtreamLoadingSubtitle = computed(
89	        () =>
90	            this.catalog.provider === 'xtream' &&
91	            this.isPaginatedContentLoading()
92	    );
93	    readonly categoryItemSubtitle = computed(() => {
94	        if (this.isXtreamLoadingSubtitle()) {
95	            return this.translate.instant(
96	                'WORKSPACE.SHELL.XTREAM_IMPORT_LOADING'
97	            );
98	        }
99	
100	        const itemCount = this.categoryItemCount();
101	        return `${itemCount} ${itemCount === 1 ? 'item' : 'items'}`;
102	    });
103	    readonly canSortContent = computed(() => this.contentSortMode() !== null);
104	    readonly searchTerm = toSignal(
105	        this.activatedRoute.queryParamMap.pipe(map((p) => p.get('q') ?? '')),
106	        { initialValue: '' }
107	    );
108	    readonly selectedDetailComponent = computed(() =>
109	        this.selectedItem() ? this.detailComponent : null
110	    );
111	    readonly contentWithProgress = computed(() =>
112	        (this.paginatedContent() ?? []).map((item: CategoryContentItem) => ({
113	            ...item,
114	            ...this.catalog.getItemProgress(item),
115	        }))
116	    );
117	
118	    setContentSortMode(mode: PortalCatalogSortMode): void {
119	        this.catalog.setContentSortMode(mode);
120	    }
121	
122	    ngOnInit(): void {
123	        this.activatedRoute.paramMap
124	            .pipe(takeUntilDestroyed(this.destroyRef))
125	            .subscribe((params) => {
126	                this.catalog.initialize(params.get('categoryId'));
127	                this.openStalkerItemFromNavigationState();
128	            });
129	
130	        this.activatedRoute.queryParamMap
131	            .pipe(takeUntilDestroyed(this.destroyRef))
132	            .subscribe((params) => {
133	                this.catalog.setSearchQuery?.(params.get('q') ?? '');
134	                this.catalog.setPage(this.toPageIndex(params.get('page')));
135	            });
136	    }
137	
138	    onPageChange(event: PageEvent): void {
139	        this.catalog.setPage(event.pageIndex);
140	        this.catalog.setLimit(event.pageSize);
141	        this.scrollGridToTop();
142	
143	        void this.router.navigate([], {
144	            relativeTo: this.activatedRoute,
145	            queryParams: {
146	                page: event.pageIndex > 0 ? event.pageIndex + 1 : null,
147	            },
148	            queryParamsHandling: 'merge',
149	            replaceUrl: true,
150	        });
151	    }
152	
153	    onItemClick(item: CategoryContentItem): void {
154	        const navigation = this.catalog.selectItem(item);
155	        if (navigation?.length) {
156	            this.router.navigate(navigation, {
157	                relativeTo: this.activatedRoute,
158	                queryParamsHandling: 'preserve',
159	            });
160	        }
161	    }
162	
163	    private toPageIndex(value: string | null): number {
164	        const page = Number(value);
165	        return Number.isInteger(page) && page > 0 ? page - 1 : 0;
166	    }
167	
168	    private scrollGridToTop(): void {
169	        const gridList = this.hostElement.nativeElement.querySelector(
170	            'app-grid-list'
171	        ) as HTMLElement | null;
172	        gridList?.scrollTo?.({ top: 0 });
173	    }
174	
175	    private openStalkerItemFromNavigationState(): void {
176	        if (this.catalog.provider !== 'stalker') {
177	            return;
178	        }
179	
180	        const item = getOpenStalkerItemState(window.history.state);
181	        if (!item) {
182	            return;
183	        }
184	
185	        this.catalog.selectItem(item as CategoryContentItem);
186	        clearNavigationStateKeys([
187	            OPEN_STALKER_ITEM_STATE_KEY,
188	            'openFavoriteItem',
189	            'openRecentItem',
190	        ]);
191	    }
192	}

