}

.channels-list {
    display: flex;
    flex-direction: column;
    height: 100%;
    overflow: hidden;
    width: 100%;
}

.scroll-viewport-portals {
    height: 100%;
    width: 100%;
    padding: 4px 8px 12px;
    box-sizing: border-box;

    ::ng-deep .cdk-virtual-scroll-content-wrapper {
        width: 100% !important;
        max-width: 100% !important;
        contain: layout style;
    }
}

.search-panel {
    padding: 10px 12px;
    flex-shrink: 0;
    height: 56px;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    background: var(--app-widget-header-bg, var(--mat-sys-surface-container-high));
    border-bottom: 1px solid var(--app-separator);
    app-region: drag;
}

.search-field {
    flex: 1;
    width: 100%;
    height: 36px;
    border-radius: 10px;
    border: 1px solid rgba(127, 127, 127, 0.22);
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0)),
        rgba(127, 127, 127, 0.08);
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 0 12px;
    box-sizing: border-box;
    cursor: text;
    transition:
        border-color 0.15s ease,
        background-color 0.15s ease,
        box-shadow 0.15s ease;

    &:focus-within {
        border-color: var(--app-selection-border);
        box-shadow: 0 0 0 3px color-mix(in srgb, var(--app-selection-color) 16%, transparent);
    }

    mat-icon {
        width: 18px;
        height: 18px;
        font-size: 18px;
        opacity: 0.68;
        flex-shrink: 0;
    }

    input {
        flex: 1;
        border: none;
        outline: none;
        background: transparent;
        color: inherit;
        font: inherit;
        font-size: 0.875rem;

        &:disabled {
            cursor: not-allowed;
            opacity: 0.5;
        }

        &::placeholder {
            opacity: 0.62;
        }
    }
}

