.channels-loading-state {
    display: grid;
    gap: 14px;
    height: 100%;
    padding: 16px 12px 18px;
}

.channels-loading-state__copy {
    padding: 0 4px;
}

.channels-loading-state__title {
    font-size: 0.86rem;
    font-weight: 600;
    letter-spacing: -0.01em;
    color: var(--mat-sys-on-surface);
}

.channels-loading-state__list {
    display: grid;
    gap: 8px;
    overflow: hidden;
}

.channel-skeleton {
    display: grid;
    grid-template-columns: 44px minmax(0, 1fr);
    grid-template-rows: 14px 10px;
    align-items: center;
    gap: 8px 12px;
    min-height: 68px;
    padding: 10px 12px;
    border-radius: 14px;
    background: color-mix(
        in srgb,
        var(--app-widget-header-bg, var(--mat-sys-surface-container-high)) 88%,
        var(--app-widget-bg, var(--mat-sys-surface-container)) 12%
    );
    border: 1px solid
        color-mix(
            in srgb,
            var(--app-widget-header-border, var(--mat-sys-outline-variant)) 96%,
            transparent
        );
}

.channel-skeleton__logo,
.channel-skeleton__title,
.channel-skeleton__meta {
    position: relative;
    overflow: hidden;
    background: color-mix(
        in srgb,
        var(--app-widget-header-bg, var(--mat-sys-surface-container-high)) 52%,
        var(--app-body-color, var(--mat-sys-on-surface-variant)) 48%
    );

    &::after {
        content: '';
        position: absolute;
        inset: 0;
        background: linear-gradient(
            100deg,
            transparent 8%,
            color-mix(
                    in srgb,
                    var(--app-heading-color, var(--mat-sys-on-surface)) 18%,
                    transparent
                )
                44%,
            transparent 74%
        );
        transform: translateX(-120%);
        animation: channel-skeleton-shimmer 1.15s ease-in-out infinite;
    }
}

.channel-skeleton__logo {
    grid-row: 1 / span 2;
    width: 44px;
    height: 44px;
    border-radius: 12px;
}

.channel-skeleton__title {
    height: 11px;
    width: min(68%, 180px);
    border-radius: 999px;
}

.channel-skeleton__meta {
    height: 9px;
    width: min(42%, 120px);
    border-radius: 999px;
}

@container (max-width: 350px) {
    .scroll-viewport-portals {
        padding-inline: 6px;
    }
}

@keyframes fade-in {
    from {
        opacity: 0;
        transform: translateY(10px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes channel-skeleton-shimmer {
    100% {
        transform: translateX(120%);
    }
}

